 ('aa-24-100','https://i.postimg.cc/SxNxDZzR/24v1.png',0),('aa-24-100','https://i.postimg.cc/9Q8FSGGp/24v2.png',1),('aa-24-100','https://i.postimg.cc/Gp4h1HK1/24v3.png',2),
 ('aa-12-100','https://i.postimg.cc/tRWJTnjq/12v1.png',0),('aa-12-100','https://i.postimg.cc/4N13vCyj/12v2.png',1),('aa-12-100','https://i.postimg.cc/5NJ0F94w/12v3.png',2),
 ('ab-12-100','https://i.postimg.cc/MHmzYR61/bike12v1.png',0),('ab-12-100','https://i.postimg.cc/8kRkD8Rs/bike12v2.png',1),
 ('ab-13-100','https://i.postimg.cc/BQJSnhpp/bike13v1.png',0),('ab-13-100','https://i.postimg.cc/xTg0JKF2/bike13v2.png',1),
 ('ac-12-100','https://i.postimg.cc/NjzBbQcC/REPTv1.png',0),('ac-13-100','https://i.postimg.cc/Z5RJrC1y/gotionv1.png',0),
 ('ac-14-100','https://onvolt.pl/wp-content/uploads/2025/09/a4b761cb-b394-4957-bd4e-a49e6b5b6c6d.jpg',0)
